using Godot;
using GArray = Godot.Collections.Array;

/// <summary>村庄与中世界共用的轴向六边形网格、实体占据和高亮渲染。</summary>
public partial class HexWorldMap : Node2D
{
    public const int WORLD_MAP_MODE=0, VILLAGE_MODE=1;
    [Signal] public delegate void cell_clickedEventHandler(Vector2I cell,InputEventMouseButton @event);
    [Signal] public delegate void entity_clicked_on_cellEventHandler(WorldEntity entity,Vector2I cell,InputEventMouseButton @event);
    [Export] public int map_radius=8; [Export] public float hex_size=100,hex_padding=1,hex_aspect_ratio=1; [Export] public bool draw_village_grid;
    [Export] public Color hex_fill_color=new(.25f,.35f,.3f,.9f),hex_line_color=new(.5f,.7f,.5f),highlight_select_fill=new(1,.85f,.15f,.4f),highlight_select_line=new(1,.75f,0,.95f),highlight_hover_fill=new(1,.55f,.15f,.25f),highlight_hover_line=new(1,.45f,0,.75f);
    [Export] public float hex_line_width=2;
    public int game_mode=VILLAGE_MODE; private WorldMapData? _world_data; public Godot.Collections.Array<Vector2I> cells=[]; private readonly System.Collections.Generic.Dictionary<Vector2I,float> _terrain=[]; private readonly System.Collections.Generic.Dictionary<Vector2I,float> _fertility=[]; private readonly System.Collections.Generic.Dictionary<Vector2I,WorldEntity> _occupants=[]; private readonly System.Collections.Generic.Dictionary<WorldEntity,Vector2I> _entity_cells=[]; private readonly System.Collections.Generic.Dictionary<Vector2I,Godot.Collections.Array<WorldEntity>> _characters=[]; private readonly System.Collections.Generic.Dictionary<Vector2I,Godot.Collections.Array<WorldEntity>> _items=[];
    private Node2D? _entity_layer; private Vector2I _selected=invalid(),_hover=invalid(); private Godot.Collections.Array<Vector2I> _preview=[]; private Vector2I _preview_target=invalid(); private Godot.Collections.Array<string> _zones=[]; private string _highlight_zone=""; private Vector2I _last_click=invalid(); private ulong _last_click_time;
    private static Vector2I invalid()=>new(-9999,-9999);
    public override void _Ready(){AddToGroup("hex_world_map");CallDeferred(nameof(deferred_init));}
    private void deferred_init(){generate_grid();generate_village_terrain();ensure_entity_layer();QueueRedraw();}
    private void ensure_entity_layer(){_entity_layer=GetNodeOrNull<Node2D>("EntityLayer");if(_entity_layer is null){_entity_layer=new Node2D{Name="EntityLayer",YSortEnabled=true};AddChild(_entity_layer);}}
    public Node2D get_entity_layer(){ensure_entity_layer();return _entity_layer!;}
    public void set_mode(int mode,WorldMapData? world_data=null){game_mode=mode;_world_data=world_data;if(mode==WORLD_MAP_MODE&&world_data is not null){cells=world_data.get_all_cells();_terrain.Clear();foreach(var cell in cells)_terrain[cell]=world_data.get_cell(cell)?.terrain??0;}else{generate_grid();generate_village_terrain();}clear_occupancy();QueueRedraw();}
    public void generate_grid(){cells.Clear();for(var q=-map_radius;q<=map_radius;q++)for(var r=Mathf.Max(-map_radius,-q-map_radius);r<=Mathf.Min(map_radius,-q+map_radius);r++){var cell=new Vector2I(q,r);cells.Add(cell);_terrain[cell]=0;_fertility[cell]=Mathf.Clamp(.5f+(float)GD.RandRange(-.35,.35),0,1);}}
    public void generate_village_terrain(){foreach(var cell in cells){var distance=hex_distance(cell,Vector2I.Zero);_terrain[cell]=distance>map_radius-2&&GD.Randf()>.5f?1:0;}}
    public Vector2 axial_to_local(Vector2I axial)=>new(hex_size*1.5f*axial.X*hex_aspect_ratio,hex_size*Mathf.Sqrt(3)*(axial.Y+axial.X*.5f)); public Vector2 cell_to_world(Vector2I axial)=>ToGlobal(axial_to_local(axial)); public Vector2I world_to_cell(Vector2 world_pos)=>axial_round(local_to_axial_float(ToLocal(world_pos)));
    public Vector2I pick_cell_at_world_pos(Vector2 p)=>world_to_cell(p); public Vector2 local_to_axial_float(Vector2 local){var q=local.X/(hex_size*1.5f*hex_aspect_ratio);return new Vector2(q,local.Y/(hex_size*Mathf.Sqrt(3))-q*.5f);} public Vector2I axial_round(Vector2 value){var q=Mathf.RoundToInt(value.X);var r=Mathf.RoundToInt(value.Y);var s=Mathf.RoundToInt(-value.X-value.Y);var qd=Mathf.Abs(q-value.X);var rd=Mathf.Abs(r-value.Y);var sd=Mathf.Abs(s+value.X+value.Y);if(qd>rd&&qd>sd)q=-r-s;else if(rd>sd)r=-q-s;return new Vector2I(q,r);}
    public Godot.Collections.Array<Vector2I> get_neighbors(Vector2I cell)=>new Godot.Collections.Array<Vector2I>{cell+new Vector2I(1,0),cell+new Vector2I(1,-1),cell+new Vector2I(0,-1),cell+new Vector2I(-1,0),cell+new Vector2I(-1,1),cell+new Vector2I(0,1)}; public int hex_distance(Vector2I a,Vector2I b){var q=a.X-b.X;var r=a.Y-b.Y;return (Mathf.Abs(q)+Mathf.Abs(r)+Mathf.Abs(q+r))/2;}
    public bool is_cell_valid(Vector2I cell)=>cells.Contains(cell); public WorldMapData.HexCell? get_world_cell(Vector2I cell)=>_world_data?.get_cell(cell); public string get_display_terrain_name(Vector2I cell)=>_world_data is not null?WorldMapData.TERRAIN_NAMES.GetValueOrDefault(get_terrain_type(cell),"未知地形").AsString():get_terrain_type(cell) switch{0=>"平原",1=>"浅水",_=>"深水"};
    public Godot.Collections.Array<string> get_world_road_summary(Vector2I cell){var result=new Godot.Collections.Array<string>();var data=_world_data?.get_cell(cell);if(data is null)return result;foreach(var neighbor in data.road_neighbors)result.Add("通向 "+(_world_data?.get_cell(neighbor)?.name??neighbor.ToString()));return result;}
    public int get_terrain_type(Vector2I cell)=>_world_data?.get_cell(cell)?.terrain??(_terrain.TryGetValue(cell,out var value)?value<.25f?0:value<.75f?1:2:0); public void set_terrain_at(Vector2I cell,int terrain){if(is_cell_valid(cell))_terrain[cell]=terrain==0?0:terrain==1?.5f:1;QueueRedraw();} public void set_terrain_r(Vector2I cell,float value){if(is_cell_valid(cell))_terrain[cell]=Mathf.Clamp(value,0,1);QueueRedraw();} public bool is_cell_passable(Vector2I cell)=>is_cell_valid(cell)&&get_terrain_type(cell) is not 1 and not 2&&!is_cell_occupied(cell); public float get_fertility(Vector2I cell)=>_fertility.GetValueOrDefault(cell,0); public bool has_trees_at(Vector2I cell)=>get_fertility(cell)>.55f; public int chop_trees_at(Vector2I cell){if(!has_trees_at(cell))return 0;_fertility[cell]=0;QueueRedraw();return 1;}
    public bool is_cell_occupied(Vector2I cell,WorldEntity? ignore_entity=null)=>_occupants.TryGetValue(cell,out var entity)&&GodotObject.IsInstanceValid(entity)&&entity!=ignore_entity; public WorldEntity? get_occupant_at(Vector2I cell)=>is_cell_occupied(cell)?_occupants[cell]:null;
    public Godot.Collections.Array<WorldEntity> get_characters_at_cell(Vector2I cell)=>new(_characters.GetValueOrDefault(cell,[]).Where(GodotObject.IsInstanceValid)); public Godot.Collections.Array<WorldEntity> get_loose_items_at(Vector2I cell)=>new(_items.GetValueOrDefault(cell,[]).Where(GodotObject.IsInstanceValid));
    public void register_entity(WorldEntity entity,Vector2I cell){if(!GodotObject.IsInstanceValid(entity)||!is_cell_valid(cell))return;ensure_entity_layer();if(entity.GetParent()!=_entity_layer)entity.Reparent(_entity_layer!);unregister_entity(entity);if(entity.entity_type is WorldEntity.EntityType.CHARACTER or WorldEntity.EntityType.BEAST){if(!_characters.TryGetValue(cell,out var list))_characters[cell]=list=[];list.Add(entity);}else{_occupants[cell]=entity;_entity_cells[entity]=cell;}entity.snap_to_hex_cell(cell,cell_to_world(cell));QueueRedraw();}
    public void unregister_entity(WorldEntity entity){if(!GodotObject.IsInstanceValid(entity))return;if(_entity_cells.Remove(entity,out var cell))_occupants.Remove(cell);foreach(var list in _characters.Values)list.Remove(entity);entity.hex_coord=invalid();entity.is_on_hex_map=false;}
    public void move_entity_to_cell(WorldEntity entity,Vector2I cell)=>register_entity(entity,cell); public Variant get_entity_cell(WorldEntity entity)=>_entity_cells.TryGetValue(entity,out var cell)?cell:default; public void clear_occupancy(){_occupants.Clear();_entity_cells.Clear();_characters.Clear();_items.Clear();}
    public void place_item_entity(WorldEntity item,Vector2I cell){if(!GodotObject.IsInstanceValid(item)||!is_cell_valid(cell))return;ensure_entity_layer();if(item.GetParent()!=_entity_layer)item.Reparent(_entity_layer!);if(!_items.TryGetValue(cell,out var list))_items[cell]=list=[];list.Add(item);item.hex_coord=cell;item.is_on_hex_map=true;item.is_item_on_map=true;item.GlobalPosition=cell_to_world(cell)+new Vector2(list.Count*12,hex_size*.15f);QueueRedraw();} public void remove_item_entity(WorldEntity item){foreach(var list in _items.Values)list.Remove(item);item.hex_coord=invalid();item.is_on_hex_map=false;item.is_item_on_map=false;QueueRedraw();}
    public void set_select_highlight(Vector2I cell){_selected=cell;QueueRedraw();} public void clear_select_highlight(){_selected=invalid();QueueRedraw();} public void set_hover_highlight(Vector2I cell){_hover=cell;QueueRedraw();} public void clear_hover_highlight(){_hover=invalid();QueueRedraw();} public void clear_all_highlights(){_selected=invalid();_hover=invalid();QueueRedraw();}
    public Godot.Collections.Array<Vector2I> get_adjacent_free_cells(Vector2I center,int count){var result=new Godot.Collections.Array<Vector2I>();foreach(var cell in new[]{center}.Concat(get_neighbors(center))){if(is_cell_valid(cell)&&!is_cell_occupied(cell)&&get_terrain_type(cell)==0)result.Add(cell);if(result.Count>=count)break;}return result;} public Godot.Collections.Array<Vector2I> get_random_free_cells(int count)=>new(cells.Where(c=>!is_cell_occupied(c)&&get_terrain_type(c)==0).OrderBy(_=>GD.Randf()).Take(count));
    public void set_preview_path(Godot.Collections.Array<Vector2I> path,Vector2I target_cell=default){_preview=path.Duplicate();_preview_target=target_cell;QueueRedraw();} public void clear_preview_path(){_preview.Clear();_preview_target=invalid();QueueRedraw();} public void set_active_zones(GArray zones){_zones.Clear();foreach(var zone in zones)_zones.Add(zone.AsString());QueueRedraw();} public void clear_active_zones(){_zones.Clear();QueueRedraw();} public void set_active_highlight_zone(string id){_highlight_zone=id;QueueRedraw();} public Godot.Collections.Array<string> get_active_zone_ids()=>_zones.Duplicate() as Godot.Collections.Array<string>??[]; public string get_active_highlight_zone()=>_highlight_zone;
    public bool is_double_click()=>_last_click==pick_cell_at_world_pos(GetGlobalMousePosition())&&Time.GetTicksMsec()-_last_click_time<360;
    public override void _UnhandledInput(InputEvent e){if(e is not InputEventMouseButton mouse||!mouse.Pressed||mouse.ButtonIndex!=MouseButton.Left)return;var cell=pick_cell_at_world_pos(mouse.Position);if(!is_cell_valid(cell))return;_last_click=cell;_last_click_time=Time.GetTicksMsec();if(get_occupant_at(cell) is { } occupant)EmitSignal(SignalName.entity_clicked_on_cell,occupant,cell,mouse);EmitSignal(SignalName.cell_clicked,cell,mouse);}
    public override void _Draw(){foreach(var cell in cells){var points=hex_vertices(axial_to_local(cell));var type=get_terrain_type(cell);DrawColoredPolygon(points,type==0?hex_fill_color:type==1?new Color(.25f,.5f,.7f):new Color(.12f,.3f,.55f));if(draw_village_grid||_world_data is not null){var line=points.Append(points[0]).ToArray();DrawPolyline(line,hex_line_color,hex_line_width,true);}if(cell==_selected)DrawColoredPolygon(points,highlight_select_fill);if(cell==_hover)DrawColoredPolygon(points,highlight_hover_fill);}if(_preview.Count>1)for(var i=1;i<_preview.Count;i++)DrawLine(axial_to_local(_preview[i-1]),axial_to_local(_preview[i]),new Color(1,.85f,.2f,.8f),4);}
    private Vector2[] hex_vertices(Vector2 c){var result=new Vector2[6];for(var i=0;i<6;i++){var angle=Mathf.Pi/3*i;result[i]=c+new Vector2(Mathf.Cos(angle)*hex_size*hex_padding*hex_aspect_ratio,Mathf.Sin(angle)*hex_size*hex_padding);}return result;}
    public void refresh_world_visibility()=>QueueRedraw(); public void refresh_vegetation()=>QueueRedraw(); public void refresh_world_textures()=>QueueRedraw(); public void refresh_layer_transforms(){} public void set_world_cell_terrain_tile(Vector2I coord)=>QueueRedraw();
}
